let studyClubData=null,studyClubLoading=false;
async function studyClubRequest(action='',data){const r=await fetch('/api/study-clubs'+action,{credentials:'same-origin',...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'정기 모임을 불러오지 못했습니다.');return d;}
async function loadStudyClubs(){
 const list=document.querySelector('#study-club-list');if(!list||studyClubLoading)return;studyClubLoading=true;
 try{const data=await studyClubRequest();if(!list.isConnected)return;studyClubData=data;const uid=window.hfAuth.user.id;
  const html=data.clubs.map(c=>{const joined=c.members.some(m=>m.id===uid),own=c.owner_id===uid,canArchive=own||(window.hfAuth.user.role==='admin'&&String(window.hfAuth.user.employee)==='56512');return `<article class="study-club-card" data-proposal-id="club-${c.id}"><div class="study-club-head"><div><h3>${esc(c.name)}</h3><p>${esc(c.restaurant)} · 매주 ${c.slot==='dinner'?'저녁':'낮'} ${esc(c.study_time)}</p></div><span class="meal-count">${c.members.length}/${c.capacity}명</span></div><p class="study-club-week">${esc(data.week)} 시작 주 · ${esc(c.author)}님의 모임${c.has_override?' · 이번 주 변경 적용 중':''}</p><div class="study-club-roster">${c.schedule.map(day=>{const confirmed=day.confirmed.includes(uid),attending=day.members.some(m=>m.id===uid);return `<section class="study-club-day ${day.day===data.today?'is-today':''}" aria-label="${studyDayNames[day.weekday]}요일 참석자"><h4>${studyDayNames[day.weekday]} <small>${day.day.slice(5).replace('-','/')}</small>${day.day===data.today?'<span>오늘</span>':''}</h4><div class="study-club-names">${day.members.map(m=>`<span>${esc(m.name)}</span>`).join('')||'<small>참석자 없음</small>'}</div><p class="study-club-count">${day.members.length}명${day.locked?` · ${day.complete?'전원 확인 완료':'완료 확인 '+day.confirmed.length+'/'+day.members.length}`:''}</p>${attending&&day.day===data.today?`<button type="button" data-study-club-complete="${c.id}" data-day="${day.day}" ${day.can_confirm?'':'disabled'}>${confirmed?'✓ 확인 완료':day.members.length<2?'2명 이상 필요':'공부 완료 확인'}</button>`:''}</section>`}).join('')}</div><div class="study-club-actions">${joined?`<button type="button" data-study-club-days="${c.id}">참여 요일 수정</button>${!own?`<button type="button" data-study-club-leave="${c.id}">모임 나가기</button>`:''}`:`<button type="button" class="primary" data-study-club-join="${c.id}" ${c.members.length>=c.capacity?'disabled':''}>${c.members.length>=c.capacity?'정원 마감':'요일 선택하고 참여'}</button>`}${canArchive?`<button type="button" class="study-club-end" data-study-club-archive="${c.id}">모임 종료</button>`:''}</div></article>`}).join('')||'<div class="meal-empty"><strong>매주 함께 공부하는 모임을 만들어 보세요</strong><p>월~금 참여 요일을 선택하면 요일별 참석자가 자동으로 표시됩니다.</p></div>';
  reconcileProposalList(list,html);
 }catch(e){if(list.isConnected)list.textContent=e.message}finally{studyClubLoading=false}
}
function studyClubDaysInputs(days){return `<fieldset class="meal-weekdays"><legend>참여 요일</legend>${studyDayNames.map((n,i)=>`<label><input type="checkbox" name="days" value="${i}" ${days.includes(i)?'checked':''}>${n}</label>`).join('')}</fieldset>`;}
function showStudyClubForm(action,id){
 let modal=document.querySelector('#study-club-dialog');if(!modal){modal=document.createElement('dialog');modal.id='study-club-dialog';document.body.append(modal)}
 const club=studyClubData?.clubs.find(c=>c.id===id),create=action==='create',edit=action==='days';
 modal.innerHTML=`<div class="progress-dialog-head"><h2>${create?'정기 공부 모임 만들기':edit?'참여 요일 수정':'정기 모임 참여'}</h2><button type="button" class="auth-link" data-study-club-close>닫기</button></div><form id="study-club-form" class="board-form" data-action="${action}" data-id="${id||''}">${create?`<label>모임 이름<input class="field" name="name" maxlength="80" placeholder="예: 퇴근 후 자격증 공부" required></label><label>공부 장소<input class="field" name="restaurant" maxlength="120" placeholder="예: 도서관" required></label><div class="study-club-form-row"><label>공부<select class="field" name="slot"><option value="lunch">낮</option><option value="dinner" selected>저녁</option></select></label><label>시간<input class="field" name="study_time" type="time" value="18:00" required></label><label>모임 정원<input class="field" name="capacity" type="number" min="2" max="30" value="8" required></label></div><p class="muted">정원은 모임 전체 회원 수이며 본인을 포함합니다.</p>`:`<p>${esc(club?.name||'')} · ${esc(club?.restaurant||'')}</p>`}${edit?'<label>변경 범위<select class="field" name="scope"><option value="week">이번 주만 변경</option><option value="default">매주 기본 요일 변경</option></select></label>':''}<div id="study-club-day-inputs">${studyClubDaysInputs(edit?club.my_week_days:[0,1,2,3,4])}</div><p class="muted" id="study-club-scope-note">${edit?'이번 주만 적용됩니다. 모두 체크 해제하면 이번 주 전체 불참입니다.':'선택한 요일로 매주 반복됩니다. 이번 주만 따로 바꿀 수도 있습니다.'}</p>${edit?'<p class="muted">완료 확인이 시작된 날은 참석자 명단이 유지됩니다.</p>':''}<button type="submit" class="primary">${create?'모임 만들기':edit?'요일 저장':'모임 참여'}</button><p class="board-status" role="status"></p></form>`;
 modal.querySelector('[data-study-club-close]').onclick=()=>modal.close();const scope=modal.querySelector('[name=scope]');if(scope)scope.onchange=()=>{modal.querySelector('#study-club-day-inputs').innerHTML=studyClubDaysInputs(scope.value==='week'?club.my_week_days:club.my_days);modal.querySelector('#study-club-scope-note').textContent=scope.value==='week'?'이번 주만 적용됩니다. 모두 체크 해제하면 이번 주 전체 불참입니다.':'기본 요일은 매주 반복됩니다. 이번 주 별도 설정이 있으면 이번 주에는 그 설정을 유지합니다.'};modal.showModal();
}
document.addEventListener('submit',async e=>{
 const f=e.target;if(f.id!=='study-club-form')return;e.preventDefault();const data=new FormData(f),action=f.dataset.action,b=f.querySelector('[type=submit]');b.disabled=true;
 try{await studyClubRequest('/'+action,{...Object.fromEntries(data),id:Number(f.dataset.id),days:data.getAll('days').map(Number),capacity:Number(data.get('capacity')),week:studyClubData?.week});f.closest('dialog').close();await loadStudyClubs();}catch(error){f.querySelector('.board-status').textContent=error.message}finally{b.disabled=false}
});
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-study-club-create],[data-study-club-join],[data-study-club-days],[data-study-club-leave],[data-study-club-archive],[data-study-club-complete]');if(!b)return;
 if(b.hasAttribute('data-study-club-create')){showStudyClubForm('create');return}
 for(const action of ['join','days'])if(b.hasAttribute('data-study-club-'+action)){showStudyClubForm(action,Number(b.getAttribute('data-study-club-'+action)));return}
 const action=b.hasAttribute('data-study-club-leave')?'leave':b.hasAttribute('data-study-club-archive')?'archive':'complete',id=Number(b.getAttribute('data-study-club-'+action));
 if(action==='archive'&&!confirm('정기 모임을 종료할까요? 완료 기록과 받은 XP는 유지됩니다.'))return;
 if(action==='leave'&&!confirm('이 정기 모임에서 나갈까요?'))return;
 b.disabled=true;try{const d=await studyClubRequest('/'+action,{id,day:b.dataset.day});await loadStudyClubs();if(action==='complete'){await loadActivity();showStudyMessage(d.complete?`참여자 전원 확인 완료${d.earned?' · '+d.earned+' XP 반영':''}`:`완료 확인 ${d.confirmed}/${d.total}명 · 전원 확인하면 XP가 반영됩니다.`)}}catch(error){b.disabled=false;showStudyMessage(error.message)}
});

setInterval(()=>{if(location.hash==='#study'&&!document.hidden&&!document.querySelector('dialog[open]'))loadStudyClubs();},15000);

function showStudyMessage(message){let p=document.querySelector('#study-club-message');if(!p){p=document.createElement('p');p.id='study-club-message';p.className='notice';p.setAttribute('role','status');document.querySelector('.study-clubs-section')?.prepend(p);}p.textContent=message;}

